def transform(grid):
    out = [row[:] for row in grid]
    r = next(i for i,row in enumerate(grid) if any(v in (2,8) for v in row))
    line = grid[r]
    # Each colored symbol is raised as a column; neighboring runs of 1s encode
    # the column's height, with the colored symbol at its top.
    for c,v in enumerate(line):
        if v not in (2,8):
            continue
        # For 2 markers the run of ones immediately to the left controls height;
        # for 8 markers the run immediately to the left likewise controls height.
        n = 0
        j = c-1
        while j >= 0 and line[j] == 1:
            n += 1
            j -= 1
        height = max(1, n)
        for k in range(1, height+1):
            if r-k >= 0:
                out[r-k][c] = 1 if k < height else v
    return out
